const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const gradeW={A:1,B:.75,C:.45,D:.20};
const membershipWeight=t=>{
  if((t.confidence??0)<60)return 0;
  const p=.40+.60*((t.purity??0)/100);
  const c=.50+.50*((t.confidence??0)/100);
  return (gradeW[t.grade]??0)*p*c;
};
const weightedMean=(xs,ws)=>{
  const sw=ws.reduce((a,b)=>a+b,0);
  return sw?xs.reduce((s,x,i)=>s+x*ws[i],0)/sw:0;
};
const scale=(x,a,b)=>clamp((x-a)/(b-a)*100,0,100);

function derive(q){
  const ret=q.prevClose?((q.close/q.prevClose)-1)*100:0;
  const vr=q.avg20Volume?q.volume/q.avg20Volume:1;
  const tr=(q.turnover!=null&&q.avg20Turnover)?q.turnover/q.avg20Turnover:vr;
  const dp=q.pivot?((q.pivot-q.close)/q.pivot)*100:null;
  return {...q,returnPct:ret,relativeStrengthPct:ret-(q.marketReturnPct??0),
    volumeRatio:vr,turnoverRatio:tr,distanceToPivotPct:dp,
    nearPivot:dp!=null&&dp>=0&&dp<=8};
}

function scoreTheme(theme,members,quotes){
  const rows=[];
  for(const m of members){
    const q=quotes[m.code]; if(!q)continue;
    const w=membershipWeight(m.meta); if(!w)continue;
    rows.push({code:m.code,meta:m.meta,q:derive(q),w});
  }
  const sw=rows.reduce((s,r)=>s+r.w,0);
  if(!rows.length||!sw)return null;

  const frac=fn=>rows.reduce((s,r)=>s+(fn(r)?r.w:0),0)/sw;
  const breadth=frac(r=>r.q.returnPct>0)*100;
  const strongBreadth=frac(r=>r.q.returnPct>=2)*100;
  const money=weightedMean(rows.map(r=>scale(r.q.turnoverRatio,.5,3)),rows.map(r=>r.w));
  const vol=weightedMean(rows.map(r=>scale(r.q.volumeRatio,.6,2.5)),rows.map(r=>r.w));
  const px=weightedMean(rows.map(r=>scale(r.q.relativeStrengthPct,-3,5)),rows.map(r=>r.w));
  const bo=frac(r=>['breakout','volume_breakout'].includes(r.q.vcpStatus))*100;
  const near=frac(r=>r.q.nearPivot&&['candidate','waiting','new'].includes(r.q.vcpStatus))*100;
  const vcp=weightedMean(rows.map(r=>clamp(r.q.vcpScore??0,0,100)),rows.map(r=>r.w));
  const dryRows=rows.filter(r=>r.q.nearPivot&&r.q.contractionVolumeRatio!=null);
  const dry=dryRows.length?weightedMean(
    dryRows.map(r=>scale(.95-r.q.contractionVolumeRatio,0,.55)),
    dryRows.map(r=>r.w)):0;
  const newC=frac(r=>r.q.isNewCandidate)*100;

  // Persistence needs historical theme scores; neutral 50 until history exists.
  const persistence=50;
  const heat=clamp(.30*money+.20*breadth+.15*vol+.15*px+.15*bo+.05*persistence,0,100);
  const earlyFlow=.55*money+.45*breadth;
  const setup=clamp(.30*near+.25*vcp+.15*dry+.15*newC+.10*earlyFlow-.05*bo,0,100);

  let state='quiet';
  if(heat>=75&&setup>=60)state='active_with_setups';
  else if(setup>=70&&heat>=45&&heat<75)state='emerging';
  else if(heat>=75)state='hot';
  else if(heat>=55)state='watch';

  return {theme,heat:Math.round(heat),setup:Math.round(setup),
    breadthPct:Math.round(breadth),strongBreadthPct:Math.round(strongBreadth),
    breakoutCount:rows.filter(r=>['breakout','volume_breakout'].includes(r.q.vcpStatus)).length,
    nearPivotCount:rows.filter(r=>r.q.nearPivot).length,
    newCandidateCount:rows.filter(r=>r.q.isNewCandidate).length,
    effectiveWeight:+sw.toFixed(2),state};
}
